/**
 * Parity with evals/runner/score.py: the reports on the fixtures/sample-run folders must equal their
 * EXPECTED-SCORE.md (generated by the prototype) byte for byte, less the two comment lines at the top.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { num, scoreGolden, scoreJudge, scoreSeeded } from "../src/score.ts";

const CASES = resolve(import.meta.dirname, "..", "..", "..", "evals", "cases");
const SEEDED = join(CASES, "seeded", "SD-RA-0001-refund");
const GOLDEN = join(CASES, "golden", "G-0001-refund");
const JUDGE = join(CASES, "judge", "JF-REQ-0001-bad");

const expected = (runDir: string) =>
  readFileSync(join(runDir, "EXPECTED-SCORE.md"), "utf8").replace(/\r\n/g, "\n").replace(/^(<!--.*-->\n)+\n?/, "").trimEnd();

test("seeded: SD-RA-0001 sample run matches EXPECTED-SCORE.md exactly", () => {
  const run = join(SEEDED, "fixtures", "sample-run");
  const { data, report } = scoreSeeded(SEEDED, run);
  assert.equal(report, expected(run));
  assert.deepEqual(data.metrics, { "recall.blocker": 0.5, "recall.all": 0.8, severity_accuracy: 0.75, route_accuracy: 0.75, noise: 0.2 });
  assert.deepEqual(data.matches, { "EF-1": "RAF-1", "EF-2": "RAF-2", "EF-3": "RAF-3", "EF-5": "RAF-4" });
  assert.deepEqual(data.extras, ["RAF-5"]);
  assert.equal(data.pass, false);
});

test("golden: G-0001 sample run matches EXPECTED-SCORE.md exactly", () => {
  const run = join(GOLDEN, "fixtures", "sample-run");
  const { data, report } = scoreGolden(GOLDEN, run);
  assert.equal(report, expected(run));
  assert.deepEqual(data.metrics, { ref_coverage: 0.7, must_miss: 1 });
  assert.deepEqual(data.alignment["REQ-102"], ["REQ-002", "merged"]);
  assert.deepEqual(data.must_missed, ["REQ-003"]);
});

test("judge: the synthetic judge output meets every expected verdict", () => {
  const { data, report } = scoreJudge(JUDGE, join(JUDGE, "fixtures", "synthetic-judge-output.json"));
  assert.deepEqual(data, { case: "JF-REQ-0001-bad", verdict_accuracy: 1, verdict_ok: true });
  assert.match(report, /^\| RQ-3 \| 3–5 \| 4 \| ✓ \|/m);
  assert.match(report, /`verdict_accuracy` = 1\.0 \(release ≥ 0\.9\)$/);
});

test("judge: an out-of-range score and a wrong verdict each cost accuracy; bad output is rejected", () => {
  const dir = mkdtempSync(join(tmpdir(), "judge-"));
  try {
    const out = JSON.parse(readFileSync(join(JUDGE, "fixtures", "synthetic-judge-output.json"), "utf8"));
    out.criteria.find((c: { id: string }) => c.id === "RQ-2").score = 4;
    out.verdict = "pass";
    writeFileSync(join(dir, "out.json"), JSON.stringify(out));
    const { data, report } = scoreJudge(JUDGE, join(dir, "out.json"));
    assert.equal(data.verdict_accuracy, 0.6);
    assert.match(report, /^\| RQ-2 \| 1–2 \| 4 \| ✕ \|/m);
    assert.match(report, /judge said \*\*pass\*\* ✕/);
    writeFileSync(join(dir, "bad.json"), JSON.stringify({ verdict: "pass" }));
    assert.throws(() => scoreJudge(JUDGE, join(dir, "bad.json")), /does not match judge-output\.schema\.json/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("numbers print as the prototype printed them", () => {
  assert.equal(num(1), "1.0");
  assert.equal(num(0.85), "0.85");
  assert.equal(num(0, "must_miss"), "0");
});
